// FUNCTION ov08_02222564: matching C (pt2)
#pragma force_active on
u8 ov08_02222564(BattleParty *battleParty) {
    u16 i, numSelectablePartyPokemon = 0;

    for (i = 0; i < 6; i++) {
        if (battleParty->partyPokemon[i].species != SPECIES_NONE_PT && battleParty->partyPokemon[i].isEgg == 0) {
            numSelectablePartyPokemon++;
        }
    }

    if (numSelectablePartyPokemon >= 2) {
        return 1;
    }

    return 0;
}
